CREATE TABLE `data_statistics` (
  `stat_id` int NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `battery_id` int NOT NULL COMMENT '电池组编号',
  `voltage_mean` decimal(10,4) DEFAULT NULL COMMENT '电压均值',
  `voltage_variance` decimal(10,4) DEFAULT NULL COMMENT '电压方差',
  `voltage_min` decimal(10,4) DEFAULT NULL COMMENT '电压最小值',
  `voltage_max` decimal(10,4) DEFAULT NULL COMMENT '电压最大值',
  `voltage_std` decimal(10,4) DEFAULT NULL COMMENT '电压标准差',
  `current_mean` decimal(10,4) DEFAULT NULL COMMENT '电流均值',
  `current_variance` decimal(10,4) DEFAULT NULL COMMENT '电流方差',
  `current_min` decimal(10,4) DEFAULT NULL COMMENT '电流最小值',
  `current_max` decimal(10,4) DEFAULT NULL COMMENT '电流最大值',
  `current_std` decimal(10,4) DEFAULT NULL COMMENT '电流标准差',
  `temperature_mean` decimal(10,4) DEFAULT NULL COMMENT '温度均值',
  `temperature_variance` decimal(10,4) DEFAULT NULL COMMENT '温度方差',
  `temperature_min` decimal(10,4) DEFAULT NULL COMMENT '温度最小值',
  `temperature_max` decimal(10,4) DEFAULT NULL COMMENT '温度最大值',
  `temperature_std` decimal(10,4) DEFAULT NULL COMMENT '温度标准差',
  `capacity_mean` decimal(10,4) DEFAULT NULL COMMENT '容量均值',
  `capacity_variance` decimal(10,4) DEFAULT NULL COMMENT '容量方差',
  `capacity_min` decimal(10,4) DEFAULT NULL COMMENT '容量最小值',
  `capacity_max` decimal(10,4) DEFAULT NULL COMMENT '容量最大值',
  `capacity_std` decimal(10,4) DEFAULT NULL COMMENT '容量标准差',
  `resistance_mean` decimal(10,4) DEFAULT NULL COMMENT '内阻均值',
  `resistance_variance` decimal(10,4) DEFAULT NULL COMMENT '内阻方差',
  `resistance_min` decimal(10,4) DEFAULT NULL COMMENT '内阻最小值',
  `resistance_max` decimal(10,4) DEFAULT NULL COMMENT '内阻最大值',
  `resistance_std` decimal(10,4) DEFAULT NULL COMMENT '内阻标准差',
  `soc_mean` decimal(10,4) DEFAULT NULL COMMENT 'SOC均值',
  `soc_variance` decimal(10,4) DEFAULT NULL COMMENT 'SOC方差',
  `soc_min` decimal(10,4) DEFAULT NULL COMMENT 'SOC最小值',
  `soc_max` decimal(10,4) DEFAULT NULL COMMENT 'SOC最大值',
  `soc_std` decimal(10,4) DEFAULT NULL COMMENT 'SOC标准差',
  `soh_mean` decimal(10,4) DEFAULT NULL COMMENT 'SOH均值',
  `soh_variance` decimal(10,4) DEFAULT NULL COMMENT 'SOH方差',
  `soh_min` decimal(10,4) DEFAULT NULL COMMENT 'SOH最小值',
  `soh_max` decimal(10,4) DEFAULT NULL COMMENT 'SOH最大值',
  `soh_std` decimal(10,4) DEFAULT NULL COMMENT 'SOH标准差',
  `power_mean` decimal(10,4) DEFAULT NULL COMMENT '功率均值',
  `power_variance` decimal(10,4) DEFAULT NULL COMMENT '功率方差',
  `power_min` decimal(10,4) DEFAULT NULL COMMENT '功率最小值',
  `power_max` decimal(10,4) DEFAULT NULL COMMENT '功率最大值',
  `power_std` decimal(10,4) DEFAULT NULL COMMENT '功率标准差',
  `rul_mean` decimal(10,4) DEFAULT NULL COMMENT 'RUL均值',
  `rul_min` int DEFAULT NULL COMMENT 'RUL最小值',
  `rul_max` int DEFAULT NULL COMMENT 'RUL最大值',
  `rul_std` decimal(10,4) DEFAULT NULL COMMENT 'RUL标准差',
  `pcl_mean` decimal(10,4) DEFAULT NULL COMMENT 'PCL均值',
  `pcl_min` decimal(10,4) DEFAULT NULL COMMENT 'PCL最小值',
  `pcl_max` decimal(10,4) DEFAULT NULL COMMENT 'PCL最大值',
  `pcl_std` decimal(10,4) DEFAULT NULL COMMENT 'PCL标准差',
  `total_cycles` int DEFAULT NULL COMMENT '总循环次数',
  `data_completeness` decimal(5,4) DEFAULT '1.0000' COMMENT '数据完整性(%)',
  `last_updated` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`stat_id`),
  UNIQUE KEY `uk_battery_id` (`battery_id`),
  CONSTRAINT `data_statistics_ibfk_1` FOREIGN KEY (`battery_id`) REFERENCES `battery_info` (`battery_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据统计表';
